import json,sys
document=json.loads(sys.stdin.buffer.read().decode('utf8'))
if document.get('fail') is True:raise SystemExit(7)
mode=sys.argv[1]
if mode=='clean':text=json.dumps(document,ensure_ascii=False,sort_keys=True,separators=(',',':'))
elif mode=='smudge':text=json.dumps(document,ensure_ascii=False,sort_keys=True,indent=2)
else:raise SystemExit(8)
sys.stdout.buffer.write((text+'\n').encode('utf8'))
